window.JostMasterLibraries = JSON.parse(JSON.stringify(DEFAULT_MASTER_LIBRARIES));

function encryptMasterLibraryPayload(libraryObj = window.JostMasterLibraries) {
  try {
    const jsonStr = JSON.stringify(libraryObj);
    let encoded = '';
    const key = 'JOST_FMEA_SECURE_LIB_KEY_2026';
    for (let i = 0; i < jsonStr.length; i++) {
      encoded += String.fromCharCode(jsonStr.charCodeAt(i) ^ key.charCodeAt(i % key.length));
    }
    const b64 = btoa(unescape(encodeURIComponent(encoded)));
    return JOST_LIB_HEADER + b64;
  } catch (e) {
    console.error("Encryption failed, defaulting to JSON string:", e);
    return JSON.stringify(libraryObj);
  }
}

function decryptMasterLibraryPayload(rawContent) {
  if (!rawContent) return null;
  let text = rawContent.trim();

  if (text.startsWith(JOST_LIB_HEADER)) {
    try {
      const b64 = text.substring(JOST_LIB_HEADER.length);
      const decoded = decodeURIComponent(escape(atob(b64)));
      const key = 'JOST_FMEA_SECURE_LIB_KEY_2026';
      let jsonStr = '';
      for (let i = 0; i < decoded.length; i++) {
        jsonStr += String.fromCharCode(decoded.charCodeAt(i) ^ key.charCodeAt(i % key.length));
      }
      return JSON.parse(jsonStr);
    } catch (e) {
      console.warn("Failed to decrypt encrypted .lib payload, trying JSON parse fallback:", e);
    }
  }

  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error("Invalid .lib or JSON library file format.");
  }
}

function syncMasterLibraryWithSharePoint(incomingContent, sourceName = "SharePoint Shared Location") {
  const sharedLib = decryptMasterLibraryPayload(incomingContent);
  if (!sharedLib) throw new Error("Could not parse shared library content.");

  const currentLocalLib = window.JostMasterLibraries;
  const sharedTimestamp = new Date(sharedLib.lastUpdated || 0).getTime();
  const localTimestamp = new Date(currentLocalLib?.lastUpdated || 0).getTime();

  if (localTimestamp && sharedTimestamp && sharedTimestamp === localTimestamp) {
    console.log(`⚡ [Electron Depository] Local library timestamp (${currentLocalLib.lastUpdated}) matches ${sourceName}. Skipping update.`);
    if (typeof showToast === 'function') {
      showToast(`⚡ Local Electron library is already up-to-date (${currentLocalLib.lastUpdated}). Skipping file replacement for faster load.`, "info");
    }
    return window.JostMasterLibraries;
  }

  if (localTimestamp && sharedTimestamp && sharedTimestamp < localTimestamp) {
    console.warn(`[Electron Depository] Local library timestamp is newer than ${sourceName}. Preserving local library.`);
    return window.JostMasterLibraries;
  }

  window.JostMasterLibraries = {
    version: sharedLib.version || "2.0.0",
    lastUpdated: sharedLib.lastUpdated || new Date().toISOString(),
    preventions: Array.isArray(sharedLib.preventions) ? sharedLib.preventions : DEFAULT_MASTER_LIBRARIES.preventions,
    detections: Array.isArray(sharedLib.detections) ? sharedLib.detections : DEFAULT_MASTER_LIBRARIES.detections,
    characteristics: Array.isArray(sharedLib.characteristics) ? sharedLib.characteristics : DEFAULT_MASTER_LIBRARIES.characteristics
  };

  localStorage.setItem('jost_master_library_cache', encryptMasterLibraryPayload(window.JostMasterLibraries));

  console.log(`🔄 [Electron Depository] Successfully updated Electron library repository from ${sourceName} (Updated: ${window.JostMasterLibraries.lastUpdated})!`);
  if (typeof showToast === 'function') {
    showToast(`🔄 Synced & updated Electron local library repository from ${sourceName} (Updated: ${window.JostMasterLibraries.lastUpdated})!`, "success");
  }
  return window.JostMasterLibraries;
}

function loadMasterLibraryFromContent(content, sourceName = ".lib file") {
  return syncMasterLibraryWithSharePoint(content, sourceName);
}

function initMasterLibrary() {
  try {
    const cached = localStorage.getItem('jost_master_library_cache');
    if (cached) {
      const parsed = decryptMasterLibraryPayload(cached);
      if (parsed) window.JostMasterLibraries = parsed;
    } else {
      localStorage.setItem('jost_master_library_cache', encryptMasterLibraryPayload(DEFAULT_MASTER_LIBRARIES));
    }
  } catch (e) {
    console.warn("Could not load library cache, using default:", e);
  }
}

function exportMasterLibraryToLibFile() {
  window.JostMasterLibraries.lastUpdated = new Date().toISOString();
  localStorage.setItem('jost_master_library_cache', encryptMasterLibraryPayload(window.JostMasterLibraries));

  const encContent = encryptMasterLibraryPayload(window.JostMasterLibraries);
  const blob = new Blob([encContent], { type: 'application/octet-stream' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `jost_master_engineering_library_${new Date().toISOString().replace(/[:.]/g, '-')}.lib`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  if (typeof showToast === 'function') {
    showToast("💾 Exported Encrypted Master Library (.lib) for SharePoint storage!", "info");
  }
}

function triggerImportMasterLibraryFile() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = '.lib,.json,.txt';
  input.onchange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        syncMasterLibraryWithSharePoint(event.target.result, file.name);
      } catch (err) {
        if (typeof showToast === 'function') {
          showToast(`❌ Error loading library file: ${err.message}`, "danger");
        }
      }
    };
    reader.readAsText(file);
  };
  input.click();
}

initMasterLibrary();

window.encryptMasterLibraryPayload = encryptMasterLibraryPayload;
window.decryptMasterLibraryPayload = decryptMasterLibraryPayload;
window.syncMasterLibraryWithSharePoint = syncMasterLibraryWithSharePoint;
window.loadMasterLibraryFromContent = loadMasterLibraryFromContent;
window.exportMasterLibraryToLibFile = exportMasterLibraryToLibFile;
window.triggerImportMasterLibraryFile = triggerImportMasterLibraryFile;
